def validate_config(config, required_keys):
    missing = []
    for key in required_keys:
        if key not in config:
            missing.append(key)
    return missing

def summarize_results(results):
    summary = {'success': 0, 'failed': 0}
    for item in results:
        if item.get('returncode') == 0:
            summary['success'] += 1
        else:
            summary['failed'] += 1
    return summary

def build_report(prechecks_ok, changed, failed_items):
    failed_count = len(failed_items)
    status = 'ok' if prechecks_ok and failed_count == 0 else 'failed'
    return {
        'status': status,
        'changed': changed,
        'failed_count': failed_count,
    }
